<?php
namespace Tests\Feature;
use App\Models\{User,PortalPrivacyState as State,PortalPrivacyNotice as Notice,PortalPrivacyAcknowledgement as Ack,PortalPrivacyCase as Review};
use App\Support\{PortalPrivacy as P,TimetableGovernance as G};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class PortalPrivacyTest extends TestCase {
 use LazilyRefreshDatabase;
 private function fixture():array {$admin=User::factory()->create(['role'=>'admin']);$ceo=User::factory()->create(['role'=>'ceo']);$person=User::factory()->create(['role'=>'apprentice']);return compact('admin','ceo','person');}
 private function rev():int {return State::find(1)->revision;}
 private function draft(array $f,string $label='v1',bool $verified=true):Notice {return P::draft($f['admin'],1,$label,str_repeat('Fictional reviewed privacy information. ',10),'privacy@example.test',array_fill_keys(P::CHECKS,$verified?'Fictional verified evidence REF-42':'Pending'));}
 private function published(array $f,string $label='v1'):Notice {$n=$this->draft($f,$label);P::publish($f['ceo'],1,$n,$this->rev());return $n->refresh();}
 private function concern(array $f,Notice $n):Review {return P::concern($f['person'],1,$n->id,$n->body_hash,(string)Str::uuid(),'PRIVATE-CONCERN-TEXT');}
 private function reject(callable $fn):void {try{$fn();$this->fail('Expected checked rejection');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 public function test_pack44_shortcuts_and_saved_work_do_not_bypass_privacy_gate():void {$f=$this->fixture();$this->published($f);P::enable($f['ceo'],1,$this->rev(),true,'Reviewed rollout');$this->actingAs($f['person']);foreach(['/quick-actions','/saved-work','/record-checks','/visual-reports','/visual-reports.pdf','/centre-planning/work-moves','/centre-planning/optimiser','/reports/historical-cohorts','/centre-access','/centre-oversight','/centre-followups','/restriction-recovery','/my-calendar','/my-calendar.ics','/review-preparation','/communication-checks','/my-reminder-status']as$url){$this->get($url)->assertRedirect('/privacy');}$this->get('/privacy-information')->assertOk();}
 public function test_no_notice_or_gate_is_seeded_and_public_contact_page_is_available():void {$f=$this->fixture();$this->assertNull(P::current());$this->assertFalse(State::find(1)->enabled);$this->assertDatabaseCount('portal_privacy_notices',0);$this->get('/privacy-information')->assertOk()->assertSee('awaiting verified approval')->assertHeader('Referrer-Policy','no-referrer');}
 public function test_incomplete_facts_hold_publication_and_gate_enable():void {$f=$this->fixture();$n=$this->draft($f,'unverified',false);$this->reject(fn()=>P::publish($f['ceo'],1,$n,$this->rev()));$this->reject(fn()=>P::enable($f['ceo'],1,$this->rev(),true,'No approved notice'));$this->assertNull(P::current());}
 public function test_only_ceo_can_publish_or_enable():void {$f=$this->fixture();$n=$this->draft($f);$this->actingAs($f['admin'])->post('/privacy-administration/'.$n->id.'/publish',['revision'=>$this->rev(),'confirmed'=>1])->assertForbidden();$this->post('/privacy-administration/rollout',['revision'=>$this->rev(),'enabled'=>1,'privacy_reason'=>'Reviewed','confirmed'=>1])->assertForbidden();}
 public function test_notice_publication_does_not_silently_enable_gate():void {$f=$this->fixture();$n=$this->published($f);$this->assertSame($n->id,P::current()->id);$this->assertFalse(State::find(1)->enabled);$this->get('/privacy-information')->assertOk()->assertSee('Fictional reviewed privacy')->assertDontSee('Fictional verified evidence');}
 public function test_gate_requires_current_unticked_acknowledgement_and_records_no_consent():void {$f=$this->fixture();$n=$this->published($f);P::enable($f['ceo'],1,$this->rev(),true,'Reviewed rollout');$this->actingAs($f['person'])->get('/apprentices')->assertRedirect('/privacy');$this->get('/privacy')->assertOk()->assertDontSee('checked="checked"',false);$this->post('/privacy/acknowledge',['notice_id'=>$n->id,'body_hash'=>$n->body_hash])->assertSessionHasErrors('acknowledged');$this->post('/privacy/acknowledge',['notice_id'=>$n->id,'body_hash'=>$n->body_hash,'acknowledged'=>1])->assertRedirect('/');$this->assertTrue(P::acknowledged($f['person'],$n));$this->assertFalse(Ack::first()->proof['consent_recorded']);$this->get('/apprentices')->assertOk();}
 public function test_ack_replay_is_idempotent_and_encrypted():void {$f=$this->fixture();$n=$this->published($f);P::acknowledge($f['person'],1,$n->id,$n->body_hash);P::acknowledge($f['person'],1,$n->id,$n->body_hash);$this->assertDatabaseCount('portal_privacy_acknowledgements',1);$this->assertStringNotContainsString('acknowledgement',DB::table('portal_privacy_acknowledgements')->value('proof'));}
 public function test_new_notice_requires_new_ack_and_old_screen_is_rejected():void {$f=$this->fixture();$old=$this->published($f);P::acknowledge($f['person'],1,$old->id,$old->body_hash);$n=$this->published($f,'v2');$this->reject(fn()=>P::acknowledge($f['person'],1,$old->id,$old->body_hash));$this->assertFalse(P::acknowledged($f['person'],$n));$this->assertSame('Published',$old->fresh()->state);}
 public function test_stale_publication_revision_and_corrupt_notice_are_held():void {$f=$this->fixture();$rev=$this->rev();$this->published($f);$n=$this->draft($f,'v2');$this->reject(fn()=>P::publish($f['ceo'],1,$n,$rev));DB::table('portal_privacy_notices')->where('id',$n->id)->update(['body_hash'=>str_repeat('0',64)]);$this->reject(fn()=>P::publish($f['ceo'],1,$n,$this->rev()));}
 public function test_concern_pauses_protected_use_keeps_notice_contact_and_logout():void {$f=$this->fixture();$n=$this->published($f);$c=$this->concern($f,$n);$this->actingAs($f['person'])->get('/apprentices')->assertRedirect('/privacy');$this->get('/privacy')->assertOk()->assertSee($c->id)->assertSee('PRIVATE-CONCERN-TEXT');$this->get('/privacy-information')->assertOk();$this->post('/logout')->assertRedirect();$this->assertTrue($f['person']->fresh()->active);$this->assertDatabaseCount('portal_privacy_acknowledgements',0);}
 public function test_concern_is_encrypted_and_replay_does_not_duplicate():void {$f=$this->fixture();$n=$this->published($f);$token=(string)Str::uuid();$a=P::concern($f['person'],1,$n->id,$n->body_hash,$token,'PRIVATE-CONCERN-TEXT');$b=P::concern($f['person'],1,$n->id,$n->body_hash,$token,'PRIVATE-CONCERN-TEXT');$this->assertSame($a->id,$b->id);$this->assertStringNotContainsString('PRIVATE-CONCERN',DB::table('portal_privacy_cases')->value('details'));$this->reject(fn()=>P::acknowledge($f['person'],1,$n->id,$n->body_hash));}
 public function test_reviewed_alternative_is_time_bound_and_does_not_forge_ack():void {$f=$this->fixture();$n=$this->published($f);P::enable($f['ceo'],1,$this->rev(),true,'Rollout');$c=$this->concern($f,$n);P::decide($f['admin'],1,$c,1,'Alternative',today()->addDays(7)->toDateString(),'Checked alternative and review date');$this->actingAs($f['person'])->get('/apprentices')->assertOk();$this->assertDatabaseCount('portal_privacy_acknowledgements',0);$this->travel(8)->days();$this->get('/apprentices')->assertRedirect('/privacy');}
 public function test_alternative_is_rechecked_after_notice_change():void {$f=$this->fixture();$n=$this->published($f);$c=$this->concern($f,$n);P::decide($f['admin'],1,$c,1,'Alternative',today()->addDays(7)->toDateString(),'Reviewed');$this->published($f,'v2');$this->actingAs($f['person'])->get('/apprentices')->assertRedirect('/privacy');}
 public function test_resolving_concern_allows_own_ack_not_automatic_acceptance():void {$f=$this->fixture();$n=$this->published($f);$c=$this->concern($f,$n);P::decide($f['admin'],1,$c,1,'Resolved',null,'Concern addressed');$this->assertNull(P::open($f['person']));$this->assertDatabaseCount('portal_privacy_acknowledgements',0);P::acknowledge($f['person'],1,$n->id,$n->body_hash);$this->assertTrue(P::acknowledged($f['person'],$n));}
 #[\PHPUnit\Framework\Attributes\TestWith(['Archive-review'])] #[\PHPUnit\Framework\Attributes\TestWith(['Deletion-review'])]
 public function test_account_retention_review_queue_never_archives_or_deletes(string $action):void {$f=$this->fixture();$n=$this->published($f);$c=$this->concern($f,$n);P::decide($f['admin'],1,$c,1,$action,null,'Human retention/action review required');$this->assertTrue($f['person']->fresh()->active);$this->assertSame($action,$c->fresh()->state);$this->assertDatabaseCount('users',3);$this->actingAs($f['person'])->get('/apprentices')->assertRedirect('/privacy');}
 public function test_timetable_centre_manager_cannot_access_private_review_or_drafts():void {$f=$this->fixture();$u=User::factory()->create(['role'=>'manager']);G::role($f['admin'],1,$u,0,\App\Models\TimetableGovernanceState::find(1)->revision,'centre_manager',false,false,'Reviewed grant');$this->actingAs($u)->get('/privacy-administration')->assertForbidden();$this->post('/privacy-administration/draft',[])->assertForbidden();}
 public function test_case_version_or_proof_tamper_cannot_unlock_access():void {$f=$this->fixture();$n=$this->published($f);$c=$this->concern($f,$n);$this->reject(fn()=>P::decide($f['admin'],1,$c,99,'Resolved',null,'Stale'));DB::table('portal_privacy_cases')->where('id',$c->id)->update(['state'=>'Alternative']);$this->assertFalse(P::alternative($c->fresh(),$n));$this->reject(fn()=>P::decide($f['admin'],1,$c,1,'Resolved',null,'Tampered'));}
 public function test_required_event_failure_rolls_back_ack_and_case_decision():void {$f=$this->fixture();$n=$this->published($f);AuditFault::install('privacy_ack_fault','portal_privacy_events','Fictional failure','notice_acknowledged');try{P::acknowledge($f['person'],1,$n->id,$n->body_hash);$this->fail('Expected fault');}catch(\Illuminate\Database\QueryException){$this->assertDatabaseCount('portal_privacy_acknowledgements',0);}}
 public function test_concern_event_failure_rolls_back_pause():void {$f=$this->fixture();$n=$this->published($f);AuditFault::install('privacy_case_fault','portal_privacy_events','Fictional failure','concern_opened');try{$this->concern($f,$n);$this->fail('Expected fault');}catch(\Illuminate\Database\QueryException){$this->assertDatabaseCount('portal_privacy_cases',0);}}
 public function test_privileged_recovery_keeps_admin_review_route_and_no_forged_ack():void {$f=$this->fixture();$n=$this->published($f);$f['person']=$f['ceo'];$c=$this->concern($f,$n);$this->actingAs($f['ceo'])->get('/privacy-administration')->assertOk();P::decide($f['ceo'],1,$c,1,'Alternative',today()->addDays(7)->toDateString(),'Explicit CEO recovery; independent review to follow',true);$this->assertTrue(P::alternative($c->fresh(),$n));$this->assertDatabaseCount('portal_privacy_acknowledgements',0);}
 public function test_normal_self_review_cannot_silently_resolve_own_case():void {$f=$this->fixture();$n=$this->published($f);$f['person']=$f['admin'];$c=$this->concern($f,$n);$this->actingAs($f['admin'])->post('/privacy-administration/review/'.$c->id,['version'=>1,'action'=>'Resolved','privacy_reason'=>'Self','confirmed'=>1])->assertForbidden();}
 public function test_private_concern_is_not_flashed_after_validation_error_and_is_escaped():void {$f=$this->fixture();$n=$this->published($f);$this->actingAs($f['person'])->post('/privacy/concern',['notice_id'=>$n->id,'body_hash'=>$n->body_hash,'request_token'=>(string)Str::uuid(),'privacy_concern'=>'PRIVATE-CONCERN-TEXT'])->assertSessionHasErrors('confirmed');$this->assertNull(session()->getOldInput('privacy_concern'));$c=P::concern($f['person'],1,$n->id,$n->body_hash,(string)Str::uuid(),'<script>private-no-run</script>');$this->get('/privacy')->assertSee('&lt;script&gt;',false)->assertDontSee('<script>private-no-run</script>',false);}
 public function test_gate_state_corruption_fails_closed_but_admin_recovery_route_remains():void {$f=$this->fixture();DB::table('portal_privacy_state')->update(['revision'=>99]);$this->actingAs($f['person'])->get('/apprentices')->assertStatus(503);$this->actingAs($f['admin'])->get('/privacy-administration')->assertOk();}
 public function test_all_privacy_views_render_no_store_and_require_confirmation():void {$f=$this->fixture();$this->published($f);$this->actingAs($f['admin'])->get('/privacy-administration')->assertOk()->assertHeader('Cache-Control','no-store, private');$this->actingAs($f['person'])->get('/privacy')->assertOk()->assertHeader('Referrer-Policy','no-referrer');}
 public function test_sole_privileged_operator_has_audited_alternative_recovery_without_ack():void {$f=$this->fixture();$n=$this->published($f);$f['ceo']->forceFill(['active'=>false])->save();$f['person']=$f['admin'];$c=$this->concern($f,$n);P::decide($f['admin'],1,$c,1,'Alternative',today()->addDays(7)->toDateString(),'Sole operator recovery pending independent review',true);$this->assertTrue(P::alternative($c->fresh(),$n));$this->assertDatabaseCount('portal_privacy_acknowledgements',0);}
 public function test_duplicate_notice_label_is_a_validation_error_not_a_second_version():void {$f=$this->fixture();$this->draft($f);$this->reject(fn()=>$this->draft($f));$this->assertDatabaseCount('portal_privacy_notices',1);}
 public function test_review_event_failure_rolls_back_state_and_open_case_pointer():void {$f=$this->fixture();$n=$this->published($f);$c=$this->concern($f,$n);AuditFault::install('review_fault','portal_privacy_events','Fictional failure','concern_reviewed');try{P::decide($f['admin'],1,$c,1,'Resolved',null,'Reviewed');$this->fail('Expected fault');}catch(\Illuminate\Database\QueryException){$this->assertSame('Open',$c->fresh()->state);$this->assertSame($f['person']->id,$c->open_user_id);}}
 public function test_gate_returns_json_hold_and_retains_public_rights_link():void {$f=$this->fixture();$this->published($f);P::enable($f['ceo'],1,$this->rev(),true,'Reviewed rollout');$this->actingAs($f['person'])->getJson('/account/password')->assertStatus(409)->assertJsonPath('privacy_url',url('/privacy'));$this->get('/privacy-information')->assertOk()->assertSee('your data protection rights');}
 public function test_publication_failure_keeps_old_current_notice_and_state_revision():void {$f=$this->fixture();$old=$this->published($f);$n=$this->draft($f,'v2');$rev=$this->rev();AuditFault::install('publish_fault','portal_privacy_events','Fictional failure','notice_published');try{P::publish($f['ceo'],1,$n,$rev);$this->fail('Expected fault');}catch(\Illuminate\Database\QueryException){$this->assertSame($old->id,P::current()->id);$this->assertSame($rev,$this->rev());$this->assertSame('Draft',$n->fresh()->state);}}

}
